from lib import *
R = J('z85'); l = R['lat']; rp = R['rapid']; by = R['bytes']
def S(k): return [x for x in out('z85').split('== ')[k].splitlines()[1:] if x.strip()]
steps = [
    step(f"50 个应用实例各 watch 同一个配置节点,配置中心每 100 ms 改一次、共 30 次(1500 次推送):全部收到、没有漏;从 set 返回到回调执行的延迟中位 {l['med']:.1f} ms、p99 {l['p99']:.1f} ms、最大 {l['mx']:.1f} ms。", t=tl(S(1)), done=[0], b=bars([['中位', l['med'], f"{l['med']:.1f} ms"], ['p99', l['p99'], f"{l['p99']:.1f} ms"], ['最大', l['mx'], f"{l['mx']:.1f} ms"]], 30, done=[0, 1, 2]), kv=KV([['推送延迟(中位)', f"{l['med']:.1f} ms"], ['漏推', '0 / 1500']], ['推送延迟(中位)'])),
    step(f"连续快速更新 200 次:每个实例只收到 {rp['min']}–{rp['mx']} 次回调(中位 {rp['med']:.0f}),但最终值都是最后一次的 r199。watch 是一次性的:收到通知到重新注册之间的更新会被合并掉。配置场景只关心最终值,可以接受;如果要看每一次变更,watch 不够。", t=tl(S(2)), mark=[0], kv=KV([['200 次更新', f"回调 {rp['min']}–{rp['mx']} 次"], ['最终值', '全部一致']], ['200 次更新'])),
    step("一个实例与服务端断开约 4.4 秒,其间配置改了 3 次:断开期间没有回调;恢复连接后(4.2 s,包含重连退避)只收到最新值 during-3,中间两次对它不可见 —— 这是「最终一致」,不是「全部更新都投递」。", t=tl(S(3)), mark=[0], kv=KV([['断网期间', '无回调'], ['恢复后', '只看到最新值']], ['恢复后'])),
    step(f"新实例启动:连接 + 读取当前值共 {R['newc']:.0f} ms,读到的是最新的。所以配置中心的「读」与「订阅」是同一份数据。", t=tl(S(4)), done=[0], kv=KV([['新实例冷启动读取', f"{R['newc']:.0f} ms"]], ['新实例冷启动读取'])),
    step(f"一份 {by['size']} 字节的 JSON 放一个节点,改其中 1 项:订阅它的实例收到 {by['json']} 字节(整份重发);拆成 100 个节点,每项一个 watch:只收到 {by['per_key']} 字节。代价是 100 个 watch、100 个 znode 要管。", t=tl(S(5)), b=bars([['整份 JSON', by['json'], f"{by['json']} B"], ['每项一个节点', by['per_key'], f"{by['per_key']} B"]], 6000, mark=[0], done=[1]), kv=KV([['改 1 项', f"JSON {by['json']} B / 每项 {by['per_key']} B"]], ['改 1 项'])),
]
A = dict(
    n=85, series='zookeeper', tags='ZooKeeper,配置中心,watch,真实验证,动画演示',
    desc=f'用 ZooKeeper 当配置中心实测:50 个实例推送延迟中位 {l["med"]:.1f} ms、p99 {l["p99"]:.1f} ms、1500 次零漏推;200 次连发被合并成 {rp["min"]}–{rp["mx"]} 次回调;断开重连后只收到最新值;整份 JSON 改 1 项 {by["json"]} 字节 vs 每项一个节点 {by["per_key"]} 字节。',
    lead='配置中心是 ZooKeeper 最经典的用途之一:配置写在节点里,应用 watch 它,改了立刻推送。这篇量推送有多快、连发更新会不会丢中间值、断网重连后看到什么,以及配置放一个节点还是拆成很多个节点的流量差别。',
    facts=[(f'{l["med"]:.1f} ms', '50 个实例的推送延迟中位(p99 %.1f ms)' % l['p99']), (f'{rp["min"]}–{rp["mx"]} / 200', '连发 200 次更新时各实例收到的回调数(最终值一致)'), (f'{by["json"]} vs {by["per_key"]} B', '改 1 项:整份 JSON 与每项一个节点收到的字节')],
    body=[
        sec('推送有多快', '', term('', blk('z85', 1)), '<p>延迟是在同一台机器上量的(客户端与 ZooKeeper 都在本机),只能说明服务端处理与一次 watch 通知的开销,不含跨机网络。</p>'),
        sec('更新被合并', '', term('', blk('z85', 2)), '<p><a href="zookeeper-watcher-once.html">watch 是一次性的</a>:触发之后客户端要重新读并重新注册,这段时间里的更新只能看到最新的。kazoo 的 DataWatch 帮你自动重新注册,但合并依然存在。</p>'),
        sec('断网重连', '', term('', blk('z85', 3)), '<p>重连成功后客户端把 watch 重新注册并带上自己见过的最后事务号,服务端发现数据已经变了就立即通知,所以不会一直拿着旧配置,但中间状态看不到。</p>'),
        sec('冷启动', '', term('', blk('z85', 4))),
        sec('一个节点还是多个节点', '', term('', blk('z85', 5)), '<p>配置越大、越新越频繁,拆分的收益越明显;但一次要改多个相关项时,拆开会遇到「读到半新半旧」的问题,见<a href="zookeeper-hot-config.html">下一篇</a>。</p>'),
        sec('分步演示', '', demo('配置推送', [('t', 'term', '输出'), ('b', 'bars', '延迟 / 字节'), ('kv', 'kv', '要点')], steps, '本步的对象')),
    ],
    refs=[ENV_Z + '。kazoo 2.11.0 的 DataWatch,50 个客户端在同一进程的不同连接上,服务端与客户端都在本机;断网用 TCP 代理关闭连接并拒绝重连', '没有验证:跨机房延迟、上千个实例同时订阅同一节点的推送延迟、配置大于 1 MiB(见第 1、22 篇)、权限控制(ACL)下的配置读取'],
)
